import{z as p,x as B,o as t,c as T,q as i,j as s,D as a,d as r,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Spanner 与 TrueTime","description":"","frontmatter":{"title":"Spanner 与 TrueTime","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spanner-truetime.md","filePath":"cs/spanner-truetime.md","lastUpdated":1791413859000}'),m={name:"cs/spanner-truetime.md"};function A(d,e,c,u,_,h){const n=B("Mermaid");return t(),T("div",null,[e[2]||(e[2]=i('<h1 id="spanner-与-truetime" tabindex="-1">Spanner 与 TrueTime <a class="header-anchor" href="#spanner-与-truetime" aria-label="Permalink to &quot;Spanner 与 TrueTime&quot;">​</a></h1><div class="epigraph"><p>TrueTime 给出带误差界的时钟区间；提交等待直到区间过去，时间戳序才与真实时间外部一致。</p><footer>—— 据 Corbett et al., Spanner: Google&#39;s Globally-Distributed Database, OSDI 2012</footer></div><p><a href="/cs/percolator">上一课</a>用时间戳服务器。本课把戳绑到物理时间：Spanner 的 TrueTime API 返回 \\([t_{earliest}, t_{latest}]\\)，提交时间戳取 \\(t_{latest}\\) 并 <strong>commit wait</strong> 等到该时间真正经过。外部一致性（external consistency）：若 T1 提交结束后 T2 才开始，则 T2 的戳更大。缺口是时钟不确定度，不是再讲 2PC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨数据中心线性一致通常要共识。Spanner：数据 Paxos 组，事务跨组 2PC，时间戳来自 TrueTime。若不等待，T2 可能拿到更早戳。commit wait 用 \\(\\epsilon\\) 换外部序。缺口是 <strong>\\(\\epsilon\\) 大则写延迟大</strong>；GPS/原子钟把 \\(\\epsilon\\) 压到毫秒级，这是硬件合同。</p><p>读：当前读可能等，快照读带过去时间。与读己之写：全局戳可比较。</p><p><span class="marginnote">术语翻译：commit wait 就是「提交前先把本地时钟的不确定区间睡过去」。TrueTime 说「现在是 \\([t_e,t_l]\\) 之间的某刻」，等过了 \\(t_l\\)，这一刻就铁定成为过去，后来者的时间戳必然更大，读序不会再变。</span></p><p><span class="marginnote">Corbett et al. OSDI 2012。Cockroach 用 HLC 近似，无 Google 真时钟。本课 TrueTime 机制。计算机栏 HLC 课可对照，此处不重推混合逻辑钟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写事务：锁、2PC、打 TT.now().latest、等待。只读：选时间戳不阻塞写者（在 \\(\\epsilon\\) 规则下）。目录：分片与 Paxos 组的元数据也是 Spanner 表。</p><p>与 Calvin：Spanner 非确定性调度+锁+真时间；Calvin 定序日志。两条外部一致路线。</p>',11)),(t(),s(l,null,{default:a(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TT%5B%22TrueTime%20%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20TS%5B%22%E6%8F%90%E4%BA%A4%E6%88%B3%20%3D%20latest%22%5D%0A%20%20TS%20--%3E%20WAIT%5B%22commit%20wait%20%E8%BF%87%E5%8C%BA%E9%97%B4%22%5D%0A%20%20WAIT%20--%3E%20EXT%5B%22%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%E5%BA%8F%22%5D%0A%20%20PAX%5B%22Paxos%20%E7%BB%84%22%5D%20--%3E%20TPC%5B%22%E8%B7%A8%E7%BB%84%202PC%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(t(),s(l,null,{default:a(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BA%8B%E5%8A%A1%20T1%20%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20G%5B%22%E5%8F%96%20TT.now()%20%E7%9A%84%20latest%22%5D%0A%20%20G%20--%3E%20Q%7B%22%E7%AD%89%E5%BE%85%E5%88%B0%E5%8C%BA%E9%97%B4%E8%BF%87%E5%8E%BB%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22T2%20%E5%BC%80%E5%A7%8B%E6%97%B6%E5%BF%85%E6%8B%BF%E6%9B%B4%E5%A4%A7%E6%88%B3%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20BAD%5B%22T2%20%E5%8F%AF%E8%83%BD%E6%8B%BF%E5%88%B0%E6%97%A9%E4%BA%8E%20T1%20%E7%9C%9F%E5%AE%9E%E6%8F%90%E4%BA%A4%E7%9A%84%E6%88%B3%22%5D%0A%20%20BAD%20--%3E%20VIOL%5B%22%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%E8%A2%AB%E7%A0%B4%E5%9D%8F%22%5D%0A%20%20OK%20--%3E%20EXT%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E5%BA%8F%20%3D%20%E7%9C%9F%E5%AE%9E%E6%97%B6%E9%97%B4%E5%BA%8F%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<p>这张图回答的是：省掉 commit wait 到底坏了哪条性质——不等待时 T2 的戳可能落在 T1 真实提交时刻之前，事后用这两个戳读数据会读到与因果相反的序。</p><p><span class="marginnote">数字实例：设 \\(\\epsilon=4\\) 毫秒。每次写事务都要多等最多 4 毫秒才返回提交，一秒内做 200 次小事务就白付近 0.8 秒墙钟等待。这正是 Google 用 GPS 与原子钟把 \\(\\epsilon\\) 压到毫秒级的原因——误差每降 1 毫秒，所有写延迟的尾巴都跟着降。</span></p><p>故障：Paxos 选主，RPO 由多数盘决定。RTO 含选举。\\(\\epsilon\\) 抖动直接进尾延迟。隔离：可串行、外部一致，比 SI 强。</p><p>SQL：Spanner 提供 SQL，优化器仍要分片裁剪与 shuffle——本课不重做连接。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲分布式死锁检测算法。也不把 Spanner 当「有了就不需要校准代价模型」。NewSQL 课归类。</p><p>后课默认：真时间+等待可得外部一致时间戳。分布式死锁：2PC 与锁跨组时 WFG 跨网络。</p><p>没有误差界的 NTP 不能当 TrueTime 用。</p><p><span class="marginnote">常见误区：初学者容易以为 NTP 校准后的时钟也能当 TrueTime 用。NTP 只给一个「大概对」的值，不承诺误差上界；没有「最迟不超过 \\(t_l\\)」的合同，commit wait 就不知道该睡多久——外部一致性的代价正是这个被硬件保证的上界。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TrueTime 区间 + commit wait 给出外部一致戳。</li><li>存储用 Paxos，跨组 2PC；\\(\\epsilon\\) 进入写延迟。</li><li>分布式死锁下一课。</li><li>出处：Corbett et al., OSDI 2012。</li></ul>',11))])}const C=p(m,[["render",A]]);export{S as __pageData,C as default};
